<?php
use EIPSI\StudyEngine\Contracts\Canonical;
use EIPSI\StudyEngine\Persistence as P;
foreach(array(null,'03','04','05','06','08','02') as $fixture)pg_case('export stable schema fixture '.($fixture??'cross-sectional'),function()use($fixture){$f=pf_enroll(pf_publish($fixture));$d=pg_export($f);pe_assert($d['rows']&&$d['manifest'],'Empty export');foreach($d['rows'] as $r)pe_assert(isset($r['study_version_id'],$r['protocol_hash'],$r['question_id'],$r['response_key'],$r['occurrence_key'],$r['block_state'],$r['response_status']),'Identity absent');foreach($d['rows'] as $r)if($r['block_state']==='SCHEDULED')pe_assert($r['response_status']==='NOT_YET_AVAILABLE','Future counted as missing');pe_assert(strpos(Canonical::json($d),'seed_ref')===false&&strpos(Canonical::json($d),'seed_hex')===false,'Seed leak');});
pg_case('EMA 5 per day times 7 keeps 35 distinct occurrences',function(){ $f=pf_enroll(pf_publish('05'));$d=pg_export($f);$rows=array_values(array_filter($d['rows'],static function($r){return $r['assessment_id']==='E_EMA'&&$r['question_id']==='Q_AFFECT';}));pe_assert(count($rows)===35&&count(array_unique(array_map(static function($r){return Canonical::json($r['occurrence_key']);},$rows)))===35,'EMA collapsed');});
pg_case('RCT branches not selected export NOT_SCHEDULED not missing',function(){ $f=pf_enroll(pf_publish('06'));pf_dispatch($f,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$f['view']['next_action']['payload']['assessment_execution_id'],'responses'=>array('Q_ELIGIBLE'=>true)));$d=pg_export($f);$n=0;foreach($d['rows'] as $r)if($r['block_state']==='NOT_SCHEDULED'){$n++;pe_assert($r['response_status']==='NOT_SCHEDULED','Missing branch');}pe_assert($n>0&&strpos(Canonical::json($d['rows']),'EIPSI_RANDOM_V1')!==false,'No RCT');});
pg_case('WAIT skipped occurrences retain rule provenance',function(){ $f=pf_enroll(pf_publish('08'));pf_dispatch($f,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$f['view']['next_action']['payload']['assessment_execution_id'],'responses'=>array('Q_RISK'=>9)));$rows=pg_export($f)['rows'];$n=0;foreach($rows as $r)if(in_array($r['assessment_id'],array('E_FOLLOWUP_2','E_FOLLOWUP_3'),true)){$n++;pe_assert($r['response_status']==='SKIPPED_BY_RULE'&&$r['provenance']['rule_id']!==null,'WAIT lost provenance');}pe_assert($n===2,'Missing WAIT intermediate');});
pg_case('consent decline is termination with semantic role not withdrawal',function(){ $p=pf_publish('02');$f=pf_enroll($p);$b=$f['view']['next_action']['payload']['assessment_execution_id'];pf_dispatch($f,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$b,'responses'=>array('Q_CONSENT'=>'NO')));$d=pg_export($f);pe_assert(pg_row($f)['state']==='TERMINATED_BY_RULE'&&pg_count('withdrawal_records',$f)===0,'Consent became withdrawal');$roles=array_column($d['rows'],'semantic_role');pe_assert(in_array('INFORMED_CONSENT',$roles,true),'Consent role lost');});
pg_case('terminated execution B2 preserves historical termination',function(){ $f=pf_enroll(pf_publish('02'));pf_dispatch($f,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$f['view']['next_action']['payload']['assessment_execution_id'],'responses'=>array('Q_CONSENT'=>'NO')));pg_withdraw(pg_shell($f),'DO_NOT_USE');pe_assert(pg_row($f)['state']==='TERMINATED_BY_RULE'&&pg_export($f)['rows']===array(),'Historical termination rewritten');});
pg_case('combined V1 retired and V2 exports retain distinct manifests',function(){ $p=pf_publish();$a=pg_complete(pf_enroll($p),'v1-answer');$v2=pf_publish(null,array(),$p['definition']['study']['logical_id'],$p['public'],2);$b=pg_complete(pf_enroll($v2),'v2-answer');(new P\StudyVersionRepository(pf_db()))->retire($p['version']);$d=pg_export($a);pe_assert(count($d['manifest'])===2&&count(array_unique(array_column($d['rows'],'study_version_id')))===2,'Versions merged');});
pg_case('safe CSV reuses existing formula protection',function(){ $f=pg_complete(pf_enroll(pf_publish()),'=HYPERLINK("https://example.test")');$d=pg_export($f);$stream=fopen('php://temp','w+');$n=EIPSI_Raw_Export_Service::study_engine_csv($d,$stream);rewind($stream);$text=stream_get_contents($stream);fclose($stream);pe_assert($n===count($d['rows'])&&strpos($text,"'=HYPERLINK")!==false,'Unsafe CSV');});
pg_case('export owner denies unauthenticated caller',function(){wp_set_current_user(0);try{pe_reject(function(){EIPSI_Export_Query_Service::study_engine('ANY_STUDY');},'EXPORT_AUTHORIZATION_REQUIRED');}finally{wp_set_current_user(1);}});

pg_case('full EMA export distinguishes 35 submitted occurrences with batch query budget',function(){
 $old=$GLOBALS['pf_now'];$GLOBALS['pf_now']='2026-10-12T11:00:00Z';try{
 $f=pf_enroll(pf_publish('05'));$completed=0;
 for($step=0;$step<110;$step++){$view=pf_owner()->view($f['access']['execution_id']);$s=$view['snapshot'];$next=$view['next_action'];if($next['kind']==='FINISHED')break;
  if($next['kind']==='OPEN_ASSESSMENT'){$b=$next['payload']['assessment_execution_id'];pf_dispatch($f,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$b,'responses'=>array('Q_AFFECT'=>$completed%11,'Q_CONTEXT'=>'HOME')));$completed++;}
  else{$times=array();foreach($s['instances'] as $b)if($b['state']==='SCHEDULED'&&$b['available_at']!==null&&$b['available_at']>$s['clock'])$times[]=$b['available_at'];sort($times);pe_assert($times,'No next occurrence');pf_dispatch($f,'ADVANCE_TIME',array('at'=>$times[0]));}
 }
 global $wpdb;$before=$wpdb->num_queries;$d=pg_export($f);$queries=$wpdb->num_queries-$before;$rows=array_values(array_filter($d['rows'],static function($r){return $r['question_id']==='Q_AFFECT';}));
 pe_assert($completed===35&&count($rows)===35&&count(array_filter($rows,static function($r){return $r['response_status']==='ANSWERED';}))===35&&$queries<=12,Canonical::json(array('completed'=>$completed,'rows'=>count($rows),'answered'=>count(array_filter($rows,static function($r){return $r['response_status']==='ANSWERED';})),'queries'=>$queries)));
 }finally{$GLOBALS['pf_now']=$old;}
});
